window.addEventListener('message', function(event) {
  if (event.origin !== 'https://hellolead.pro') return;
  if (event.data === 'focus-nom') {
    const input = document.getElementById('nom');
    if (input) {
      input.focus();
      // effet propre
      input.style.boxShadow = "0 0 0 3px rgba(0,194,255,0.5)";
      setTimeout(() => {
        input.style.boxShadow = "none";
      }, 800);
    }
  }
});
